{"command": "python3 -c "
from rdkit import Chem
mol = Chem.MolFromSmiles('Cc1cn(-c2ccc(Nc3nc4c(s3)CCCC4c3ccccc3)cc2Cl)cn1')
if mol:
    print('Valid SMILES')
    print(f'Num atoms: {mol.GetNumAtoms()}')
    # Try to find the thiazole ring
    for bond in mol.GetBonds():
        if bond.GetBeginAtom().GetSymbol() == 'S':
            print(f'S bonded to: {bond.GetBeginAtom().GetIdx()} and {bond.GetEndAtom().GetIdx()}')
else:
    print('Invalid SMILES')
